create table public.hiring_pipeline_entries(id uuid primary key default gen_random_uuid(),application_id uuid not null unique references public.applications(id) on delete cascade,stage text not null check(stage in ('matched','consent','shortlist','interview','offer','hired','closed')),owner_user_id uuid references auth.users(id),stage_updated_at timestamptz not null default now());
create table public.hiring_team_notes(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id) on delete cascade,author_user_id uuid not null references auth.users(id),body text not null check(char_length(body) between 1 and 2000),created_at timestamptz not null default now());
create table public.application_decisions(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id) on delete cascade,decision text not null check(decision in ('advance','hold','reject','offer')),reason_code text not null check(reason_code in ('skill_evidence_gap','eligibility_not_met','availability_mismatch','location_mismatch','role_closed','stronger_job_related_evidence','selected','other_job_related')),evidence_note text,decided_by uuid not null references auth.users(id),decided_at timestamptz not null default now());
alter table public.hiring_pipeline_entries enable row level security;alter table public.hiring_team_notes enable row level security;alter table public.application_decisions enable row level security;
create function public.can_manage_application(app uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.applications a join public.jobs j on j.id=a.job_id where a.id=app and public.is_active_employer_member(j.organization_id))$$;
create policy "employer team manages pipeline" on public.hiring_pipeline_entries for all using(public.can_manage_application(application_id)) with check(public.can_manage_application(application_id));create policy "employer team manages notes" on public.hiring_team_notes for all using(public.can_manage_application(application_id)) with check(public.can_manage_application(application_id) and author_user_id=auth.uid());create policy "participants read decisions" on public.application_decisions for select using(public.can_manage_application(application_id) or exists(select 1 from public.applications a where a.id=application_id and a.user_id=auth.uid()));create policy "employers record decisions" on public.application_decisions for insert with check(public.can_manage_application(application_id) and decided_by=auth.uid());
